import type { MediaKind, PlayerOptions } from "../../core/types.js";

/** Creates a configured `<audio>` element. */
export function createMediaElement(kind: "audio", options: PlayerOptions): HTMLAudioElement;
/** Creates a configured `<video>` element. */
export function createMediaElement(
  kind: Exclude<MediaKind, "audio">,
  options: PlayerOptions,
): HTMLVideoElement;
export function createMediaElement(
  kind: MediaKind,
  options: PlayerOptions,
): HTMLVideoElement | HTMLAudioElement {
  const element =
    kind === "audio" ? document.createElement("audio") : document.createElement("video");

  element.className = "up-media";
  element.setAttribute("part", "media");
  element.preload = options.preload ?? "metadata";
  element.autoplay = options.autoplay ?? false;
  element.loop = options.loop ?? false;
  element.muted = options.muted ?? false;
  element.controls = options.controls === "native";
  element.setAttribute("aria-label", options.label ?? "Media");

  if (options.crossOrigin !== undefined) {
    element.crossOrigin = options.crossOrigin;
  }

  if (element instanceof HTMLVideoElement) {
    element.playsInline = options.playsInline ?? true;

    if (options.poster !== undefined) {
      element.poster = options.poster;
    }
  }

  return element;
}

/** Removes an element from the DOM, if present. */
export function removeElement(element: HTMLElement | null): void {
  element?.remove();
}

/** Creates a sandboxed iframe for third-party players. */
export function createIframe(className: string, title: string, allow: string): HTMLIFrameElement {
  const iframe = document.createElement("iframe");

  iframe.className = className;
  iframe.setAttribute("part", "media");
  iframe.setAttribute("allow", allow);
  iframe.setAttribute("allowfullscreen", "");
  iframe.setAttribute("referrerpolicy", "strict-origin-when-cross-origin");
  iframe.setAttribute("loading", "eager");
  iframe.allowFullscreen = true;
  iframe.title = title;

  return iframe;
}

/** Resolves when an iframe's document has loaded. */
export function waitForIframe(iframe: HTMLIFrameElement): Promise<void> {
  return new Promise<void>((resolve) => {
    iframe.addEventListener("load", () => resolve(), { once: true });
  });
}
